{"path":"styles.css","content":"body {
  font-family: Georgia, "Times New Roman", serif;
  background-color: #f7f3ec;
  color: #2e2a25;
  margin: 0;
  padding: 2rem;
  line-height: 1.6;
}

h1 {
  color: #7a4a21;
  border-bottom: 3px solid #d9b98a;
  padding-bottom: 0.4rem;
  max-width: 40rem;
}

p {
  max-width: 40rem;
  font-size: 1.1rem;
}

button {
  background-color: #7a4a21;
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: 0.6rem 1.2rem;
  font-size: 1rem;
  cursor: pointer;
}

button:hover {
  background-color: #5c3717;
}
"}

